'use strict';
const $=id=>document.getElementById(id);
const pill=(text,tone='')=>`<span class="pill ${tone}">${text}</span>`;
const button=(text,target,primary=false)=>`<button ${target.startsWith('!')?'data-action="'+target.slice(1)+'"':'data-go="'+target+'"'} class="${primary?'primary':''}">${text}</button>`;
const link=(text,target)=>`<button class="text" data-go="${target}">${text} →</button>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="panelhead"><h2>${title}</h2>${action}</div>${body}</section>`;
const support=(title,body)=>`<section class="support"><h3>${title}</h3>${body}</section>`;
const grid=(body,side)=>`<div class="grid"><div class="stack">${body}</div><div>${side}</div></div>`;
const row=(title,desc,tail='',icon='')=>`<div class="row"><div class="leading">${icon?'<span class="square">'+icon+'</span>':''}<div><strong>${title}</strong><p>${desc}</p></div></div><div class="tail">${tail}</div></div>`;
const kv=(key,value)=>`<div class="kv"><span>${key}</span><span>${value}</span></div>`;
const banner=(title,desc='',action='',tone='')=>`<div class="banner ${tone}"><div><b>${title}</b>${desc?'<p>'+desc+'</p>':''}</div>${action}</div>`;
const table=(heads,rows)=>`<div class="tablewrap"><table><thead><tr>${heads.map(x=>'<th scope="col">'+x+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`;
const metric=(label,value,caption)=>`<div class="metric"><span>${label}</span><strong>${value}</strong><small>${caption}</small></div>`;
const field=(name,value='',type='text',full=false,hint='')=>`<label class="field ${full?'full':''}">${name}${type==='textarea'?'<textarea>'+value+'</textarea>':type==='select'?'<select>'+value.split('|').map(x=>'<option>'+x+'</option>').join('')+'</select>':'<input type="'+type+'" value="'+value+'">'}${hint?'<small>'+hint+'</small>':''}</label>`;
const details=()=>`<details><summary>Record details & provenance</summary><p style="margin-top:12px">Synthetic offering FS-AZ-DEMO · Immutable source version 3 · Sample release 1.3. Production record IDs, hashes, timestamps, and audit events would be available here.</p></details>`;
const check=(id,text,sub='')=>`<div class="selection"><input id="${id}" type="checkbox" class="check"><label for="${id}">${text}${sub?'<small>'+sub+'</small>':''}</label></div>`;
const steps=(active)=>`<div class="flowsteps">${['Add sources','Analyze','Review records','Publish release'].map((x,i)=>`<span class="${i===active?'current':''}"><b>${i<active?'✓':i+1}</b>${x}</span>`).join('')}</div>`;
const contribution=(items)=>support('Contributes to the system package','<ol>'+items.map(x=>'<li>'+x+'</li>').join('')+'</ol>');
const missionBridge=()=>support('Mission Owner handoff','<p>Customers associate their system, apply a published release, then complete their responsibilities.</p>'+link('Preview in Systems','system-hosting'));
const sourceNote=()=>'<p class="caption">All content shown is synthetic and exists only in this design preview.</p>';
const pages=[];
function page(id,title,desc,group,tab,action,target,body){pages.push({id,title,desc,group,tab,action,target,body});}
let sim={published:false,associated:false,adopted:false,ruleSaved:false,reviewed:false,entraRole:'Evidence contributor'};

page('overview','Your provider workspace','Maintain the services and evidence Mission Owners use to prepare and sustain their ATO packages.','Overview',null,'Review pending release','release',()=>
`<div class="metrics">${metric('Published capabilities','8','Azure shared-services offering')}${metric('Needs your review','2','Proposed capability changes')}${metric('Mission systems','4','Using Azure hosting')}${metric('Customer actions','3','Awaiting impact review')}</div>`+
grid(panel('Focus for today',row('Review the next Azure service release','Two implementation changes are ready for provider review.',pill('Ready for review','purple')+button('Review release','release'),'↗')+row('Follow up on evidence access','One mission team requested the current assessment summary.',button('Review request','evidence-detail'),'▤')+row('Complete a customer service association','Harbor Logistics has an allocated scope; Mission Owner review is pending.',button('View system','customer'),'◎'))+
panel('Service offerings',table(['Offering','Published release','Source status',''],[
['Azure IL5 · Shared services<small>Azure Government · Managed hosting</small>','1.2',pill('Reviewed','green'),button('Open offering','offering')],
['Microsoft 365 · Collaboration<small>SaaS · Separate service boundary</small>','1.0',pill('Reviewed','green'),button('View service model','!saas')]
])),support('Provider perspective','<p>Maintain what your service supplies. Mission Owners complete and review what their individual systems require.</p>')+contribution(['Service and boundary descriptions','Reusable control implementations','Evidence and responsibilities','Ongoing change notices'])+support('Recent activity','<p><b>09:40</b> · Source review completed</p><p><b>Yesterday</b> · Mission association requested</p>'+link('View audit history','history'))));

page('offerings','Service offerings','Keep each service, environment, and responsibility model clearly defined.','Offerings',null,'Create offering','create',()=>
banner('One provider. Distinct services.','An Azure hosting service and a collaboration service retain separate scope and evidence.')+
panel('Your offerings','<div class="toolbar"><input aria-label="Search offerings" data-filter placeholder="Search offerings"><span class="pill">2 offerings</span></div>'+table(['Offering','Service model','Customer use','Status',''],[
['Azure IL5 · Shared services<small>Azure Government · Managed</small>','IaaS + common services','4 mission systems',pill('Release 1.2 live','green'),button('Manage','offering')],
['Microsoft 365 · Collaboration<small>Microsoft 365 DoD · SaaS</small>','Collaboration service','Separate service relationship',pill('Release 1.0 live','green'),button('Preview model','!saas')]
]))+`<div class="grid equal" style="margin-top:22px">${panel('Planning for cArmy','<p>Cloud-specific offerings and centrally managed common services, with environment-specific responsibility matrices.</p>'+button('Preview multicloud setup','!multicloud'))}${panel('Planning for Cloud One','<p>Differentiate managed, boundary-protected, and brokered service arrangements before assigning control responsibilities.</p>'+button('Preview management options','!management'))}</div>`);

page('create','Create a service offering','Start with the service identity. Add authorization sources and publish reviewed capabilities afterward.','Offerings',null,'Create draft offering','!create',()=>grid(panel('Service identity','<div class="fields">'+field('Offering name','Azure IL5 · Shared services')+field('Service model','Infrastructure + shared services|Platform service|Software as a service|Brokered cloud space','select')+field('Cloud / service environment','Azure Government|Azure commercial|AWS GovCloud — proposed support|Google Cloud — proposed support|Oracle Cloud — proposed support|Microsoft 365 DoD — proposed service model','select')+field('Management arrangement','Provider managed|Shared operations|Mission Owner managed','select')+field('Service description','Shared infrastructure and security services available to eligible mission systems.','textarea',true)+field('Service owner','Provider service operations')+field('Security contact','Provider ISSM')+'</div><div class="callout">Cloud selection describes an offering. Live integration and authorization standing are recorded separately.</div>'),support('Next steps','<ol><li>Add source material.</li><li>Review scope and responsibilities.</li><li>Publish a reviewed release.</li></ol>')+support('Existing record?','<p>Importing more sources updates this offering’s review workflow. It does not require creating another offering.</p>')+contribution(['Service description','Provider contacts','Hosting architecture context'])));

page('offering','Azure IL5 · Shared services','Manage the source-backed service baseline that customers can apply to their systems.','Offerings','Overview','Review release 1.3','release',()=>
banner('Release 1.2 is available to customers','Release 1.3 contains two proposed changes and remains unpublished.',pill('Provider review required','purple'))+
`<div class="metrics">${metric('Capabilities available','8','Reviewed release 1.2')}${metric('Mission systems','4','3 impact reviews pending')}${metric('Source documents','6','1 restricted attachment')}${metric('Open findings','1','Remediation in progress')}</div>`+
grid(panel('Complete the next release',row('Sources reviewed','Decision, responsibility matrix, and service guide retained.',pill('Complete','green'),'✓')+row('Scope confirmed','One subscription; exclusions and customer allocations recorded.',pill('Complete','green'),'✓')+row('Capability changes reviewed','Two proposed changes have supporting source citations.',pill('Complete','green'),'✓')+row('Approve and publish','Review the exact release and affected mission systems.',button('Review','release'),'4'))+
panel('Recorded authorization',kv('Reference','SYNTHETIC-AUTH-001')+kv('Decision metadata',pill('Reviewed record','green'))+kv('Review date','26 Sep 2026 · Demo')+kv('Publication standing','Independent of this decision')+link('View source-backed details','authorization')),
contribution(['Hosting and boundary description','Inherited/shared implementation statements','Evidence references and customer duties'])+missionBridge()+support('Your service team','<p><b>Jordan Davis</b> · Service owner</p><p><b>Alex Morgan</b> · Provider reviewer</p>'+link('Manage provider access','administration'))));

page('sources','Authorizations & sources','Review what the documents actually say before they support a published service release.','Offerings','Authorizations & sources','Add source material','import',()=>
grid(panel('Recorded authorization',row('SYNTHETIC-AUTH-001','Demo authority · Azure hosting boundary · source version 3',pill('Reviewed','green')+button('View record','authorization'),'▤'))+
panel('Source packages & documents',table(['Source','Analysis','Review',''],[
['Azure service package · v3<small>Decision, service guide, matrix, assessment references</small>','5 of 6 files analyzed',pill('1 file needs action','amber'),button('Review package','analysis')],
['Customer responsibility matrix<small>Source page 12 · retained version 3</small>','Analyzed',pill('Reviewed','green'),button('Review source','source-review')],
['Shared-services assessment summary<small>Approved customer-facing summary</small>','Analyzed',pill('Shareable','green'),button('View evidence','evidence-detail')]
])),support('Keep the distinctions','<p><b>Authorization:</b> a recorded external decision.</p><p><b>Source package:</b> retained supporting documents.</p><p><b>Service release:</b> reviewed implementations customers can use.</p>')+contribution(['Leveraged authorization references','Source citations for narratives','Supporting artifact index'])));

page('import','Add source material','Attach documents to this offering. SPIN proposes records for review before anything reaches customers.','Offerings','Authorizations & sources','Analyze sample sources','!analyze',()=>steps(0)+grid(panel('Choose source files','<div class="dropzone"><div class="uploadicon">↥</div><h2>ATO package or individual documents</h2><p>Decision letters, service guides, control exports, responsibility matrices, and evidence.</p>'+button('Load demo files','!load-files',true)+'<p class="caption">Prototype uses built-in sample files. No real upload occurs.</p></div><div id="files" style="margin-top:18px">'+row('synthetic-azure-service-package.zip','6 files · 4.2 MB · Illustrative sample',pill('Ready','purple'))+'</div><div class="fields" style="margin-top:22px">'+field('Source type','Service authorization package|Responsibility matrix|Service guide|Assessment evidence','select')+field('Default visibility','Provider private|Approved customer summary','select')+'</div>'),support('Review stays in the portal','<p>Provider onboarding can accept this package without showing every extracted record. Continue its review here after onboarding.</p>')+support('What happens next','<ol><li>Inspect all supported files.</li><li>Flag unreadable or excluded content.</li><li>Propose distinct record types.</li><li>Review and explicitly publish.</li></ol>')));

page('analysis','Review package analysis','Resolve source exceptions, then review the proposed records by their purpose.','Offerings','Authorizations & sources','Review proposed records','source-review',()=>steps(1)+banner('One document needs attention','An encrypted attachment could not be analyzed. It is not included in the proposed release.',button('Resolve exception','!exception'),'amber')+
`<div class="metrics">${metric('Source files','6','5 analyzed · 1 encrypted')}${metric('Proposed records','12','Grouped by purpose')}${metric('Capability changes','2','Candidates, not published')}${metric('Coverage exceptions','1','Explicit resolution required')}</div>`+
grid(panel('Proposed records',row('Authorization details','1 source-backed decision proposal',pill('Reviewed','green')+button('View','authorization'),'▤')+row('Boundary & services','2 components and 1 scope statement',button('Review','scope'),'◇')+row('Capabilities & responsibilities','2 capability updates and 4 duty statements',button('Review records','source-review'),'✓')+row('Assessment references','2 evidence records',button('Review evidence','evidence'),'▧'))+panel('Source coverage',table(['File','Result',''],[['service-guide.pdf',pill('Analyzed','green'),'14 pages'],['responsibility-matrix.xlsx',pill('Analyzed','green'),'24 rows'],['restricted-attachment.pdf',pill('Encrypted','amber'),button('Resolve','!exception')]])),support('Source coverage matters','<p>Analyzed files and reviewed proposals are separate measures. An excluded or unreadable file cannot support a full-coverage claim.</p>')+contribution(['Reviewed decision metadata','Candidate implementation statements','Evidence provenance'])));

page('source-review','Review an extracted implementation','Compare the proposal with its source, confirm customer duties, and retain your rationale.','Offerings','Authorizations & sources','Save review','!review',()=>steps(2)+`<div class="grid equal">${panel('Retained source','<div class="eyebrow">Service guide · v3 · page 12</div><h2>Centralized audit collection</h2><div class="quote"><p>“The provider collects platform audit events and retains them for 90 days. Mission teams configure application log export and retain additional history required for their system.”</p><small>Synthetic source excerpt · Illustrative implementation</small></div>'+kv('Document visibility','Provider private')+kv('Candidate confidence','Requires human review')+button('View source details','!source'))}${panel('Proposed capability','<div class="fields">'+field('Capability name','Centralized audit collection','text',true)+field('Control reference','AU-6 · illustrative mapping')+field('Responsibility','Shared|Provider|Customer','select')+field('Provider implementation','Collect platform audit events and retain them for 90 days.','textarea',true)+field('Mission Owner duty','Configure application log export and preserve additional required history.','textarea',true)+field('Review rationale','Matches the quoted service guide; customer retention remains an explicit duty.','textarea',true)+'</div>'+check('source-confirm','I reviewed the source and the proposed responsibility split.'))}</div>`);

page('authorization','Recorded authorization','Inspect the external decision and the exact boundary it references.','Offerings','Authorizations & sources','Review supporting source','!source',()=>
banner('Synthetic authorization record','This example is not a Navy authorization or a verified provider decision.',pill('Design data'))+
grid(panel('Decision as recorded',kv('Reference','SYNTHETIC-AUTH-001')+kv('Record type','Provider platform decision')+kv('Issuing authority','Demo Authorizing Official')+kv('Effective date','01 Aug 2026 · Synthetic')+kv('Expiration date','31 Jul 2027 · Synthetic')+kv('Decision as stated','Approved with documented conditions')+kv('Boundary','Azure shared-services boundary · v3')+kv('Metadata review','Alex Morgan · 26 Sep 2026')+details())+panel('Conditions & supporting records',row('Applies only to the recorded service boundary','Customer workloads retain their mission-specific duties.',button('View scope','scope'))+row('Quarterly service evidence review','Illustrative decision condition; not a policy default.',button('View evidence','evidence'))),support('Document contribution','<p>This record supplies the actual title, authority, decision, dates, scope, and citations for leveraged-authorization documentation.</p>')+support('Upstream authorizations','<p>Underlying cloud references remain separate records, with their own issuer and applicability.</p>'+button('Preview upstream record','!upstream'))+support('Record a change','<p>Renewal, withdrawal, or changed conditions create a retained successor and impact review.</p>'+link('Review changes','changes'))));

