page('scope-edit','Propose a scope update','Review the next version without altering the scope used by existing releases.','Offerings','Services & scope','Save proposed scope','!scope',()=>grid(panel('Scope definition','<div class="fields">'+field('Scope name','Azure shared-services boundary · v4','text',true)+field('Cloud environment','Azure Government|Azure commercial','select')+field('Directory','Flank Speed demo directory','select')+field('Subscription','FS-Shared · Demo subscription','select')+field('Scope level','Resource group|Subscription|Resource','select')+field('Included scope','harbor-prod|atlas-prod|shared-services','select')+field('Purpose','Production shared-service allocation')+field('Exclusions','Mission application configuration and customer-operated data stores.','textarea',true)+field('Change rationale','Clarify the resources supplied to Harbor Logistics without expanding its recorded authorization.','textarea',true)+'</div>'),support('Versioned change','<p>Saving creates a proposal. Existing mission associations and prior exports keep their retained versions.</p>')+support('Next review','<p>SPIN should identify affected allocations and capability releases before this scope is used.</p>'+link('Preview impact','impact'))));

