function stateContent(state,p){const map={empty:['Start with one reviewed record','There are no records in this illustrative view yet. Add the appropriate source or service record, then review its contribution to customer documentation.','＋','Add source material','import'],error:['This information is temporarily unavailable','The last request did not return usable data. Existing records are preserved; availability is unknown rather than zero.','!','Retry preview','!retry'],restricted:['Access is required for this task','Your current role can view the service summary, but this action requires explicit permission from the record owner.','⌑','Review access options','!request']};const x=map[state];return '<section class="empty"><div class="symbol">'+x[2]+'</div><h2>'+x[0]+'</h2><p>'+x[1]+'</p>'+button(x[3],x[4],true)+'<p class="caption">Alternate state preview for '+p.title+'.</p></section>';}
function render(){const p=pageById(active)||pages[0];const system=p.id.startsWith('system-');document.title='SPIN mock · '+p.title;
 $('workspace').textContent=system?'Maritime Operations · Demo':'Flank Speed · Demo';$('workspaceSub').textContent=system?'Organization workspace · Harbor Logistics · ISSM':'Provider workspace · Provider administrator';$('switch').textContent=system?'Preview provider view ↗':'Preview Mission Owner view ↗';$('switch').dataset.go=system?'overview':'system-hosting';
 $('sidebar').innerHTML='<small>'+(system?'HARBOR LOGISTICS':'PROVIDER WORKSPACE')+'</small>'+(system?systemNav:providerNav).map(([name,id,icon])=>`<button ${id.startsWith('!')?'data-action="'+id.slice(1)+'"':'data-go="'+id+'"'} class="${p.group===name?'active':''}" ${p.group===name?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icon}</span>${name}</button>`).join('')+'<div class="navfoot"><b>Every record has a purpose</b>Reviewed sources → system documentation → ongoing monitoring.<a href="gallery.html">Browse all mockups ↗</a><a href="../system-overview-mock/pages.html">Systems design suite ↗</a></div>';
 $('breadcrumb').textContent=system?'Systems / Harbor Logistics / '+p.group:'Provider / '+p.group+(p.tab?' / Azure IL5 · Shared services':'');$('eyebrow').textContent=system?'MISSION OWNER WORKSPACE':p.tab?'AZURE IL5 · SHARED SERVICES':'PROVIDER OPERATIONS';$('title').textContent=p.title;$('description').textContent=p.desc;$('actions').innerHTML=button(p.action,p.target,true);
 const ts=system?(systemTabs[p.group]||[]):p.tab?tabs:[];$('tabs').innerHTML=ts.map(([name,id])=>`<button data-go="${id}" class="${system?id===p.id?'active':'':name===p.tab?'active':''}" ${system?id===p.id?'aria-current="page"':'':name===p.tab?'aria-current="page"':''}>${name}</button>`).join('');
 const state=$('state').value;$('content').innerHTML=state==='ready'?p.body():stateContent(state,p);$('actions').hidden=state!=='ready';$('footnote').textContent=`${pages.indexOf(p)+1} / ${pages.length} screens · Synthetic design data · ${system?'Companion to the Systems redesign':'Provider records feed mission documentation'}`;$('screen').value=p.id;$('next').onclick=()=>go(pages[(pages.indexOf(p)+1)%pages.length].id);
}
$('screen').innerHTML='<optgroup label="Provider workspace">'+pages.filter(p=>!p.id.startsWith('system-')).map(p=>`<option value="${p.id}">${p.title}</option>`).join('')+'</optgroup><optgroup label="Systems handoff">'+pages.filter(p=>p.id.startsWith('system-')).map(p=>`<option value="${p.id}">${p.title}</option>`).join('')+'</optgroup>';
$('screen').onchange=e=>go(e.target.value);$('state').onchange=render;$('close').onclick=()=>$('dialog').close();
document.addEventListener('click',e=>{const goButton=e.target.closest('[data-go]');if(goButton){if($('dialog').open)$('dialog').close();$('state').value='ready';go(goButton.dataset.go);return;}const a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='retry'){$('state').value='ready';render();toast('Sample data restored.');}else action(a.dataset.action);}});
document.addEventListener('input',e=>{if(!e.target.matches('[data-filter]'))return;const term=e.target.value.toLowerCase();e.target.closest('.panel').querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(term));});
window.addEventListener('hashchange',()=>{active=location.hash.slice(1);if(!pageById(active))active='overview';render();});active=pageById(location.hash.slice(1))?location.hash.slice(1):'overview';render();
window.mockPages=pages.map(({id,title,desc,group})=>({id,title,desc,group}));
